// @ts-strict-ignore
import {
  validateEmail,
  validatePhone,
  validateBirthDate,
  validateZipNo,
  validateLicensePlate,
} from "./validation-helper";
import { debounce, isBoolean } from "lodash-es";
import SessionStorageHelper from "@/core/helpers/session-storage-helper";
import LocalStorageHelper from "@/core/helpers/local-storage-helper";
import DateHelper, { createDate } from "@/core/helpers/date-helper";
import { isNonEmptyArray } from "@/core/helpers/array-helper";
import {
  useState,
  useCallback,
  useRef,
  Dispatch,
  SetStateAction,
  RefObject,
  useMemo,
  MutableRefObject,
  Ref,
} from "react";
import { autoCompleteValues } from "@/core/components/primitives/input-field/input-field";
import { CalendarDatesProps } from "@/core/components/primitives/calendar-date-field/calendar-date-field";
import animatedScrollTo from "animated-scroll-to";

export type ValidationType =
  | "EMAIL"
  | "PHONE"
  | "BIRTHDATE"
  | "CONTACT"
  | "ZIPCODE"
  | "TERMS_AND_CONDITIONS_CHECKBOX"
  | "LICENSE_PLATE"
  | "DATE";

export const VALIDATION_TYPES: { [val: string]: ValidationType } = {
  EMAIL: "EMAIL",
  PHONE: "PHONE",
  BIRTHDATE: "BIRTHDATE",
  CONTACT: "CONTACT",
  ZIPCODE: "ZIPCODE",
  TERMS_AND_CONDITIONS_CHECKBOX: "TERMS_AND_CONDITIONS_CHECKBOX",
  LICENSE_PLATE: "LICENSE_PLATE",
  DATE: "DATE",
};

type FieldType =
  | "INPUT_FIELD"
  | "DATE_FIELD"
  | "IMAGE_FIELD"
  | "SELECT_BOX"
  | "CHECK_BOX"
  | "AMOUNT_FIELD"
  | "TEXT_AREA";

export type InputRefType =
  | HTMLInputElement
  | HTMLSelectElement
  | HTMLTextAreaElement
  | HTMLButtonElement
  | HTMLDivElement
  | null;
export type InputRefObject = RefObject<InputRefType>;
export type InputModeTypes = "text" | "search" | "email" | "tel" | "url" | "numeric" | "none" | "decimal";

type OptionsType = {
  value?: string;
  isRequired?: boolean;
  validationType?: ValidationType;
  isEditable?: boolean;
  errorText?: string;
  label?: string;
  placeholder?: string;
  type?: FieldType;
  autoComplete?: autoCompleteValues;
  helperText?: string;
  selectBoxOptions?: Array<{ value: string; label: string }>;
  selectableCalendarDates?: CalendarDatesProps;
  fullyBookedDates?: CalendarDatesProps;
  checkBoxOptions?: Array<{ value: string; label: string }>;
  fieldId?: string;
  baseAmount?: boolean;
  price?: number;
  priceType?: string;
  minValue?: number;
  maxValue?: number;
  removeDaysInThePast?: boolean;
  inputRef?: InputRefObject;
  inputMode?: InputModeTypes;
};

export type FormField = {
  name: string;
  isValid: boolean | null;
} & OptionsType;

export type Form = {
  fields: Map<string, FormField>;
};

export type HandleFieldOnChangeFunc = (
  name: string,
  value: string | number,
  options?: { instantValidate?: boolean; isValid?: boolean },
) => void;

type FormValidationFunc = () => FormValidationResult;
type FormValidationFuncWithError = () => { form: Form; formValidationError: FormValidationError | null };
type FocusOnFunc = (fieldName: string | "FIRST_INVALID", scrollToField?: boolean) => void;

export type FormValidationResult = {
  form: Form;
  isFormValid: boolean;
};

export const FIELD_TYPES: { [key: string]: FieldType } = {
  INPUT_FIELD: "INPUT_FIELD",
  DATE_FIELD: "DATE_FIELD",
  IMAGE_FIELD: "IMAGE_FIELD",
  SELECT_BOX: "SELECT_BOX",
  CHECK_BOX: "CHECK_BOX",
  AMOUNT_FIELD: "AMOUNT_FIELD",
  TEXT_AREA: "TEXT_AREA",
};

type storageType = "sessionStorage" | "localStorage";

const saveFormValues = (
  form: Form,
  key: string,
  storageType: storageType = "sessionStorage",
  storageTimeInMinutes?: number,
  ignoreFields?: Array<string>,
): void => {
  if (!form || form.fields === null || form.fields.size === 0 || !key) {
    throw Error("Missing params to saveFormValues.");
  }

  const formFieldsToSave = isNonEmptyArray(ignoreFields)
    ? [...form.fields.values()].filter((field) => !ignoreFields.includes(field.name))
    : [...form.fields.values()];

  const formFieldNameAndValues = formFieldsToSave.reduce<Record<string, string>>((nameValueObject, field) => {
    if (!field.value) {
      return nameValueObject;
    }

    nameValueObject[field.name] = field.value;
    return nameValueObject;
  }, {});

  const storageTime =
    typeof storageTimeInMinutes === "number" && storageTimeInMinutes > 0
      ? DateHelper.addMinutes(createDate(), storageTimeInMinutes).getTime()
      : null;

  if (storageType === "sessionStorage") {
    SessionStorageHelper.setItem(key, formFieldNameAndValues, storageTime);
  } else {
    LocalStorageHelper.setItem(key, formFieldNameAndValues, storageTime);
  }
};

const restoreFormValues = (
  form: Form,
  key: string,
  storageType: storageType = "sessionStorage",
  ignoreFields?: Array<string>,
): Form => {
  if (!form || form.fields === null || form.fields.size === 0 || !key) {
    throw Error("Missing params to restoreFormValues.");
  }
  const formCopy = { ...form };
  const formFieldsNameValues: Record<string, string> =
    storageType === "sessionStorage" ? SessionStorageHelper.getItem(key) : LocalStorageHelper.getItem(key);

  if (!formFieldsNameValues) {
    return formCopy;
  }

  for (const key in formFieldsNameValues) {
    if (!Object.hasOwn(formFieldsNameValues, key)) {
      continue;
    }

    if (isNonEmptyArray(ignoreFields) && ignoreFields.includes(key)) {
      continue;
    }
    const field = formCopy.fields.get(key);
    field.value = formFieldsNameValues[key];
    const validatedField = validateField(field);
    formCopy.fields.set(field.name, validatedField);
  }

  return formCopy;
};

/** Shared functions start */
const getInitialForm = (fields = new Map()) => {
  return {
    fields: fields,
    isFormValid: null,
  };
};

const buildField = (
  name: string,
  options: OptionsType = {
    value: undefined,
    isRequired: undefined,
    validationType: undefined,
    isEditable: undefined,
    errorText: undefined,
    label: undefined,
    placeholder: undefined,
    type: undefined,
    autoComplete: undefined,
    helperText: undefined,
    selectBoxOptions: undefined,
    selectableCalendarDates: undefined,
    fullyBookedDates: undefined,
    checkBoxOptions: undefined,
    fieldId: undefined,
    price: undefined,
    priceType: undefined,
    baseAmount: false,
    minValue: undefined,
    maxValue: undefined,
    removeDaysInThePast: undefined,
    inputRef: undefined,
  },
): FormField => {
  const defaultOptions = {
    value: null,
    isRequired: false,
    validationType: null,
    isEditable: true,
    errorText: null,
    label: null,
    placeholder: null,
    type: FIELD_TYPES.INPUT_FIELD,
    autoComplete: null,
    helperText: null,
    selectBoxOptions: [],
    selectableCalendarDates: null,
    fullyBookedDates: null,
    checkBoxOptions: [],
    fieldId: null,
    price: null,
    priceType: null,
    baseAmount: false,
    minValue: null,
    maxValue: null,
    removeDaysInThePast: null,
    inputRef: null,
  };

  const merged = { ...defaultOptions, ...options };

  return {
    name: name,
    value: merged.value,
    isValid: null,
    errorText: merged.errorText,
    validationType: merged.validationType,
    isRequired: merged.isRequired,
    isEditable: merged.isEditable,
    label: merged.label,
    placeholder: merged.placeholder,
    type: merged.type,
    autoComplete: merged.autoComplete,
    helperText: merged.helperText,
    selectBoxOptions: merged.selectBoxOptions,
    selectableCalendarDates: merged.selectableCalendarDates,
    fullyBookedDates: merged.fullyBookedDates,
    checkBoxOptions: merged.checkBoxOptions,
    fieldId: merged.fieldId,
    price: merged.price,
    priceType: merged.priceType,
    baseAmount: merged.baseAmount,
    minValue: merged.minValue,
    maxValue: merged.maxValue,
    removeDaysInThePast: merged.removeDaysInThePast,
    inputRef: merged.inputRef,
    inputMode: merged.inputMode,
  };
};

/** @deprecated Use `_getValidationError` instead since that can return which fields are not valid */
const _validateForm = (form: Form) => {
  const isValid = true;
  for (const field of form.fields.values()) {
    if (field.isEditable) {
      if (
        field.isValid === false ||
        (field.isRequired && isEmpty(field.value)) ||
        (field.isRequired && field.value.length === 0)
      ) {
        return false;
      }
    }

    if (field.isRequired && field.isValid === false) {
      return false;
    }

    if (field.isRequired && field.isValid === null) {
      const validatedField = validateField(field);
      if (validatedField.isValid === false) {
        return false;
      }
    }
  }

  return isValid;
};

export type FormValidationError = Map<string, "REQUIRED_BUT_EMPTY" | "INVALID_VALIDATION">;

/** Used to check validation of a form and return which fields are not valid and why */
const _getValidationError = (form: Form): FormValidationError | null => {
  const validationError = new Map<string, "REQUIRED_BUT_EMPTY" | "INVALID_VALIDATION">();
  for (const field of form.fields.values()) {
    if (field.isEditable && field.isRequired && isEmpty(field.value)) {
      validationError.set(field.name, "REQUIRED_BUT_EMPTY");
      continue;
    }
    if (field.isEditable && field.isValid === false) {
      validationError.set(field.name, "INVALID_VALIDATION");
      continue;
    }
    if (field.isEditable && field.isValid === null) {
      const validatedField = validateField(field);
      if (validatedField.isValid === false) {
        validationError.set(field.name, "INVALID_VALIDATION");
      }
    }
  }

  return validationError.size > 0 ? validationError : null;
};

const _validateAndUpdateForm = (form: Form): Form => {
  const formCopy = { ...form };
  for (const field of formCopy.fields.values()) {
    const validatedField = validateField(field);
    formCopy.fields.set(field.name, validatedField);
  }
  return formCopy;
};

const validateField = (field: FormField): FormField => {
  const validField = { isValid: true };
  const fieldCopy = { ...field };

  if (!field.isEditable) {
    return fieldCopy;
  }

  if (fieldCopy.isRequired && isEmpty(fieldCopy.value)) {
    fieldCopy.isValid = false;
    return fieldCopy;
  }

  if (fieldCopy.validationType) {
    if (fieldCopy.validationType === VALIDATION_TYPES.ZIPCODE) {
      fieldCopy.value = fieldCopy.value.replace(/\s/g, ""); // Remove spaces for ZIPCODE validation
    }

    const isValid = validateForType(fieldCopy.value, fieldCopy.validationType);
    const hasValue = fieldCopy.value !== undefined && fieldCopy.value !== null && fieldCopy.value !== "";

    if (!isValid && hasValue) {
      fieldCopy.isValid = false;
      return fieldCopy;
    }
  }

  if (fieldCopy.type === "AMOUNT_FIELD") {
    const numericValue = Number(fieldCopy.value ?? 0);
    const hasValue = fieldCopy.value !== undefined && fieldCopy.value !== null && fieldCopy.value !== "";

    // Validate min/max if field is required OR if field has a value
    if (fieldCopy.isRequired || hasValue) {
      if (
        (fieldCopy.minValue != null && numericValue < fieldCopy.minValue) ||
        (fieldCopy.maxValue != null && numericValue > fieldCopy.maxValue)
      ) {
        fieldCopy.isValid = false;
        return fieldCopy;
      }
    }
  }

  return { ...fieldCopy, ...validField };
};

const validateForType = (value, type) => {
  // Add more types and check CONSTANT_STRING instead
  switch (type) {
    case VALIDATION_TYPES.EMAIL:
      return validateEmail(value);
    case VALIDATION_TYPES.PHONE:
      return validatePhone(value);
    case VALIDATION_TYPES.BIRTHDATE: {
      return validateBirthDate(value, 1, 120);
    }
    case VALIDATION_TYPES.LICENSE_PLATE: {
      return validateLicensePlate(value);
    }
    case VALIDATION_TYPES.CONTACT:
      if (validateEmail(value) || validatePhone(value)) {
        return true;
      }
      return false;
    case VALIDATION_TYPES.ZIPCODE:
      return validateZipNo(value);
    case VALIDATION_TYPES.DATE:
      // No format check needed - a date is set by picking one from the calendar. The required/empty
      // case is handled earlier in validateField, so any present value is considered valid here.
      return true;
    case VALIDATION_TYPES.TERMS_AND_CONDITIONS_CHECKBOX:
      for (const checkbox of value) {
        if (checkbox.checked) {
          return true;
        }
      }
      return false;
  }
  return null;
};

const isEmpty = (value?: string) => {
  return !value || value === "";
};
/** Shared functions end */

/**
 * Form builder as hook
 * @param initialForm Form object made up of properties created by buildField
 * @param autoCreateRefs Automatically create refs for all fields that don't have one
 * @returns [form, isFormValid, handleFieldOnChange, setForm, validateForm, getFormValidation, focusOn]
 */
const useForm = (
  initialForm?: Form,
  autoCreateRefs = false,
): [
  Form,
  boolean,
  HandleFieldOnChangeFunc,
  Dispatch<SetStateAction<Form>>,
  FormValidationFunc,
  FormValidationFuncWithError,
  FocusOnFunc,
] => {
  // Auto-create refs for fields that don't have them if autoCreateRefs is true
  const formWithRefs = useMemo(() => {
    if (!initialForm || !autoCreateRefs) return initialForm;

    const fieldsWithRefs = new Map(
      [...initialForm.fields.entries()].map(([key, field]) => [
        key,
        field.inputRef ? field : { ...field, inputRef: { current: null } },
      ]),
    );

    return { ...initialForm, fields: fieldsWithRefs };
  }, [initialForm, autoCreateRefs]);

  const [form, setForm] = useState<Form>(formWithRefs);
  const [isFormValid, setIsFormValid] = useState(false);
  const [debouncedValidateFieldsMap, setDebouncedValidateFieldsMap] = useState(new Map());
  const formRef = useRef(form);
  formRef.current = form;

  const handleFieldOnChange = useCallback<HandleFieldOnChangeFunc>(
    (
      name: string,
      value: string,
      options: { instantValidate: boolean; isValid?: boolean } = { instantValidate: false },
    ) => {
      const field = { ...formRef.current.fields.get(name) };
      field.value = value;
      const updatedForm = {
        fields: new Map(formRef.current.fields),
      };

      if (isBoolean(options.isValid)) {
        updatedForm.fields.set(name, { ...field, isValid: options.isValid });
        setForm(updatedForm);
        setIsFormValid(_validateForm(updatedForm));
        return;
      }

      if (field.isValid !== null || options.instantValidate) {
        const validatedField = validateField(field);
        updatedForm.fields.set(name, validatedField);
        setForm(updatedForm);
        setIsFormValid(_validateForm(updatedForm));
      } else {
        updatedForm.fields.set(name, field);
        setForm(updatedForm);
        debouncedValidation(name);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [],
  );

  const validateAndSaveField = useCallback((name) => {
    const validatedField = validateField(formRef.current.fields.get(name));
    const updatedForm = {
      fields: new Map(formRef.current.fields),
    };
    updatedForm.fields.set(name, validatedField);

    setForm(updatedForm);
    setIsFormValid(_validateForm(updatedForm));
  }, []);

  const debouncedValidation = useCallback(
    (fieldName, debounceTime = 1000) => {
      const debouncedFunctionForField = debouncedValidateFieldsMap.get(fieldName);
      if (!debouncedFunctionForField) {
        const debouncedValidateFields = debounce(() => {
          validateAndSaveField(fieldName);
        }, debounceTime);
        debouncedValidateFieldsMap.set(fieldName, debouncedValidateFields);
        setDebouncedValidateFieldsMap(debouncedValidateFieldsMap);
        debouncedValidateFields();
      } else {
        debouncedFunctionForField.cancel();
        debouncedFunctionForField(fieldName);
      }
    },
    [debouncedValidateFieldsMap, setDebouncedValidateFieldsMap, validateAndSaveField],
  );

  /**
   * @deprecated Use `getFormValidation` instead since that returns the form and formValidation
   * Validates form and updates state of each field and also returns the complete isFormValid state
   * Will update internal state of form and isFormValid before returning them both
   * @returns {FormValidationResult} FormValidationResult object
   */
  const validateForm = useCallback<FormValidationFunc>(() => {
    const updatedForm = _validateAndUpdateForm(formRef.current);
    const isFormValid = _validateForm(updatedForm);
    setForm(updatedForm);
    setIsFormValid(isFormValid);
    return { form: { ...updatedForm }, isFormValid: isFormValid };
  }, []);

  /**
   * Validates form and updates state of each field and also returns the complete form and formValidation
   * Will update internal state of form and isFormValid before returning them both
   */
  const getFormValidation = useCallback<FormValidationFuncWithError>((updateForm = true) => {
    const updatedForm = _validateAndUpdateForm(formRef.current);
    const formValidation = _getValidationError(updatedForm);
    if (updateForm) {
      setForm(updatedForm);
    }
    setIsFormValid(formValidation === null);
    return { form: { ...updatedForm }, formValidationError: formValidation };
  }, []);

  /**
   * Focuses on a specific field or the first invalid field with smooth scrolling
   * @param fieldName - Name of the field to focus on, or "FIRST_INVALID" to focus on first invalid field
   * @param scrollToField - Whether to scroll to the field (default: true)
   */
  const focusOn = useCallback<FocusOnFunc>((fieldName, scrollToField = true) => {
    let field: FormField | undefined = undefined;
    if (fieldName === "FIRST_INVALID") {
      // Use centralized validation logic to find invalid fields
      const validationErrors = _getValidationError(formRef.current);
      // Find first invalid field in form order that has a ref
      field = Array.from(formRef.current.fields.values()).find(
        (f) => f.inputRef?.current && f.isEditable && validationErrors?.has(f.name),
      );
    } else {
      // Focus on specific field
      field = formRef.current.fields.get(fieldName);
      if (!field?.isEditable) return;
    }
    if (!field) return;

    if (scrollToField) {
      animatedScrollTo(field.inputRef.current, { verticalOffset: -100, speed: 1000 });
      field.inputRef.current.focus({ preventScroll: false });
    } else {
      field.inputRef.current.focus();
    }
  }, []);

  return [form, isFormValid, handleFieldOnChange, setForm, validateForm, getFormValidation, focusOn];
};

/**
 * Assigns a HTML element to multiple refs
 * @param {HTMLElement} element HTML element to assign to refs
 * @param {Array} refs Array of refs to assign the element to
 */
const assignToRefs = <T extends InputRefType>(element: T | null, ...refs: Array<Ref<T> | undefined>) => {
  refs.forEach((ref) => {
    if (ref && typeof ref === "object" && "current" in ref) {
      (ref as MutableRefObject<T>).current = element;
    } else if (ref && typeof ref === "function") {
      ref(element);
    }
  });
};

/**
 * Form builder for class components
 * @param {String} formName Name of form object in state
 * @param {Component} component Reference to class component
 */
const FormBuilder = (formName, component) => {
  const validateAndSaveField = (name) => {
    const validatedField = validateField(component.state[formName].fields.get(name));

    const updatedForm = {
      fields: new Map(component.state[formName].fields) as Map<string, FormField>,
      isFormValid: component.state[formName].isFormValid,
    };

    updatedForm.fields.set(name, validatedField);
    updatedForm.isFormValid = _validateForm(updatedForm);

    component.setState({ [formName]: updatedForm });
  };

  const handleFieldOnChange = (name, value, options = { instantValidate: false }) => {
    const field = { ...component.state[formName].fields.get(name) };
    field.value = value;

    const updatedForm = {
      fields: new Map(component.state[formName].fields) as Map<string, FormField>,
      isFormValid: component.state[formName].isFormValid,
    };

    if (field.isValid !== null || options.instantValidate) {
      const validatedField = validateField(field);
      updatedForm.fields.set(name, validatedField);
      updatedForm.isFormValid = _validateForm(updatedForm);
      component.setState({ [formName]: updatedForm });
    } else {
      updatedForm.fields.set(name, field);
      component.setState({ [formName]: updatedForm }, () => debouncedValidation(name));
    }
  };

  const debouncedValidateFieldsMap = new Map();

  const debouncedValidation = (fieldName, debounceTime = 1000) => {
    const debouncedFunctionForField = debouncedValidateFieldsMap.get(fieldName);
    if (!debouncedFunctionForField) {
      const debouncedValidateFields = debounce(() => validateAndSaveField(fieldName), debounceTime);
      debouncedValidateFieldsMap.set(fieldName, debouncedValidateFields);
      debouncedValidateFields();
    } else {
      debouncedFunctionForField.cancel();
      debouncedFunctionForField(fieldName);
    }
  };

  return {
    handleFieldOnChange: handleFieldOnChange,
  };
};

export default FormBuilder;
export {
  useForm,
  buildField,
  _validateForm as validateForm,
  _getValidationError as getValidationError,
  validateField,
  getInitialForm,
  saveFormValues,
  restoreFormValues,
  assignToRefs,
};
